    def __init__(self, X, Y, max_len=5):
        self.X = X
        self.Y = Y
        self.max_len = max_len
    def __len__(self):
        return len(self.X)
    def __getitem__(self, index):
        x = self.X[index]
        y = self.Y[index]

        if len(x) >= self.max_len:
            x = x[:self.max_len]
        else:
            x_padded = torch.zeros(self.max_len, dtype=x.dtype)
            x_padded[:len(x)] = x
            x = x_padded

        return x, y

dataset = sentimentdata_test(X_test, y_test, max_len=5)
loader = DataLoader(dataset, batch_size=2)

